/**
 * The shared shell every justpae email is built from — the two Supabase auth
 * templates today (generated by scripts/build-emails.ts, which imports this
 * module directly), and the app's own transactional emails (KYC, withdrawals,
 * support) later. One place means a brand update happens once, not once per
 * email.
 *
 * Constraints this follows throughout, because email HTML is not web HTML:
 * - Table-based layout, not flex/grid — most clients' rendering engines
 *   predate both.
 * - Every style inline. A <style> block is allowed ONLY for the
 *   prefers-color-scheme block below, because that is the one thing that
 *   cannot be expressed as an inline attribute — and plenty of clients strip
 *   <style> entirely, so nothing in it is ever the only copy of a rule.
 * - No external stylesheet, no web font. A linked resource is one more thing
 *   that can fail to load, and most clients block remote content pre-open
 *   anyway. System font stack only.
 * - No JavaScript. It will not run anywhere that matters.
 */

export interface EmailButton {
  label: string;
  href: string;
}

export interface EmailOptions {
  /** <title> and the suggested dashboard subject line — not shown in the body. */
  subject: string;
  /** Hidden preview-pane summary. Padded with &zwnj;/&nbsp; so trailing body
   *  text can't bleed into the inbox preview snippet after it. */
  preheader: string;
  heading: string;
  /** Each string becomes one paragraph, in order, before the panel (if any). */
  bodyParagraphs: string[];
  /** The highlighted block for a verification code — raw HTML, sized and
   *  spaced by the caller since only the caller knows what's actually in it. */
  panelHtml?: string;
  /**
   * Optional, because not every email has somewhere to send you. The auth
   * templates do ("Verify your email"); a notification that a payout recipient
   * changed, or that a PIN locked, is a statement of fact — giving it a button
   * means inventing a destination, and an email whose only action is "log in"
   * trains people to click links in emails about their money, which is exactly
   * the habit a fintech should not be building.
   *
   * When omitted, the button row AND the plain-text fallback-link row are both
   * dropped — the fallback only exists to rescue a button that didn't render.
   */
  button?: EmailButton;
  /** The plain-text fallback link's own intro line, e.g. "If the button
   *  doesn't work, copy this address into your browser:". href reused from
   *  `button`. Ignored when there is no button. */
  fallbackIntro?: string;
  /** Paragraphs after the button/fallback block, before the footer — e.g.
   *  "If you didn't request this, you can ignore this email." */
  closingParagraphs?: string[];
}

const LIGHT = {
  outerBg: "hsl(var(--jp-background))",
  cardBg: "hsl(var(--jp-card))",
  cardBorder: "hsl(var(--jp-border))",
  headerBg: "hsl(var(--jp-primary))",
  heading: "hsl(var(--jp-foreground))",
  body: "hsl(var(--jp-foreground))",
  muted: "hsl(var(--jp-muted-foreground))",
  panelBg: "hsl(var(--jp-secondary))",
  panelBorder: "hsl(var(--jp-border))",
  panelText: "hsl(var(--jp-foreground))",
  footerText: "hsl(var(--jp-muted-foreground))",
};

// justpae's own dark theme, reused as the email's dark-mode palette — for the
// clients that honour prefers-color-scheme (notably Apple/iOS Mail; most
// webmail strips the <style> block below and simply stays on the light
// design, which is why that one is the one built to stand on its own).
const DARK = {
  outerBg: "hsl(var(--jp-background))",
  cardBg: "hsl(var(--jp-card))",
  cardBorder: "hsl(var(--jp-border))",
  headerBg: "hsl(var(--jp-primary))",
  heading: "hsl(var(--jp-foreground))",
  body: "hsl(var(--jp-foreground))",
  muted: "hsl(var(--jp-muted-foreground))",
  panelBg: "hsl(var(--jp-secondary))",
  panelBorder: "hsl(var(--jp-border))",
  panelText: "hsl(var(--jp-foreground))",
  footerText: "hsl(var(--jp-muted-foreground))",
};

// Royal blue, with white on it: 5.85:1, and the same button a customer sees
// in the app.
const BRAND = "#2f54eb";
const BRAND_TEXT = "#ffffff";

// Single-quoted family names, not double: every one of these sits inside a
// double-quoted HTML style="..." attribute, and a bare " here would close
// that attribute early and truncate everything after it — which is exactly
// what happened the first time this used double quotes.
// Clash Grotesk first — it is the product's only family, and a mail client
// that happens to have it installed should use it. Most will not, and no web
// font can be linked here (see the file-level note), so a system sans stack
// carries the rest. NO serif anywhere, including the heading, which used to
// have a Georgia stack of its own.
const FONT = `'Clash Grotesk',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif`;
const MONO = `'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace`;

/** Set once, from a Vercel env var, and omitted from the footer entirely
 *  when unset — see README.md in supabase/email-templates for why this
 *  isn't a hardcoded string: a footer address is required by anti-spam law
 *  in several jurisdictions this product operates in, and a wrong or
 *  invented one is worse than a missing one. */
function companyAddress(): string | null {
  return process.env.COMPANY_ADDRESS?.trim() || null;
}

// className goes on every individual <p>, not on a wrapping element: each of
// these also carries its own inline color, and a child's inherited value —
// even one set !important on an ancestor — never overrides a value the
// child specifies directly on itself. The class has to sit where the color
// does, every time, or the !important override silently does nothing.
function paragraphs(items: string[], color: string, className: string): string {
  return items
    .map(
      (p) =>
        `<p class="${className}" style="margin:12px 0 0 0;font-family:${FONT};font-size:16px;line-height:1.6;color:${color};">${p}</p>`,
    )
    .join("\n");
}

/** The bulletproof button: a VML roundrect for Outlook's Word engine (which
 *  ignores border-radius and padding on a plain <a>), and the ordinary
 *  table-cell button for everything else — each hidden from the other via
 *  conditional comments, not CSS, since Outlook's engine doesn't run CSS
 *  conditionals reliably either. */
function bulletproofButton(button: EmailButton): string {
  return `<!--[if mso]>
<v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w="urn:schemas-microsoft-com:office:word" href="${button.href}" style="height:48px;v-text-anchor:middle;width:240px;" arcsize="50%" strokecolor="${BRAND}" fillcolor="${BRAND}">
<w:anchorlock/>
<center style="color:${BRAND_TEXT};font-family:sans-serif;font-size:16px;font-weight:600;">${button.label}</center>
</v:roundrect>
<![endif]-->
<!--[if !mso]><!-- -->
<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="mso-hide:all;">
  <tr>
    <td align="center" bgcolor="${BRAND}" style="border-radius:24px;background-color:${BRAND};">
      <a href="${button.href}" target="_blank" style="display:inline-block;height:48px;line-height:48px;padding:0 32px;font-family:${FONT};font-size:16px;font-weight:600;color:${BRAND_TEXT};text-decoration:none;border-radius:24px;">${button.label}</a>
    </td>
  </tr>
</table>
<!--<![endif]-->`;
}

export function renderEmail(options: EmailOptions): string {
  const {
    subject,
    preheader,
    heading,
    bodyParagraphs,
    panelHtml,
    button,
    fallbackIntro = "If the button doesn't work, copy this address into your browser:",
    closingParagraphs = [],
  } = options;
  const address = companyAddress();

  return `<!doctype html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="X-UA-Compatible" content="IE=edge">
<meta name="color-scheme" content="light dark">
<meta name="supported-color-schemes" content="light dark">
<title>${subject}</title>
<!--[if mso]>
<noscript>
<xml>
<o:OfficeDocumentSettings>
<o:PixelsPerInch>96</o:PixelsPerInch>
</o:OfficeDocumentSettings>
</xml>
</noscript>
<![endif]-->
<style>
  /* Honoured by Apple/iOS Mail and some webmail; stripped outright by Gmail
     and others, which is why the light design above is the one that must
     stand on its own with no help from this block. */
  @media (prefers-color-scheme: dark) {
    .email-outer-bg { background-color: ${DARK.outerBg} !important; }
    .email-card-bg { background-color: ${DARK.cardBg} !important; border-color: ${DARK.cardBorder} !important; }
    .email-heading { color: ${DARK.heading} !important; }
    .email-body { color: ${DARK.body} !important; }
    .email-muted { color: ${DARK.muted} !important; }
    .email-panel-bg { background-color: ${DARK.panelBg} !important; border-color: ${DARK.panelBorder} !important; }
    .email-panel-text { color: ${DARK.panelText} !important; }
    .email-footer-text { color: ${DARK.footerText} !important; }
  }
</style>
</head>
<body style="margin:0;padding:0;background-color:${LIGHT.outerBg};">
<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;opacity:0;">${preheader}&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;&nbsp;&zwnj;</div>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${LIGHT.outerBg}" class="email-outer-bg" style="background-color:${LIGHT.outerBg};margin:0;padding:32px 0;">
  <tr>
    <td align="center">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;">
        <tr>
          <td class="email-card-bg" bgcolor="${LIGHT.cardBg}" style="background-color:${LIGHT.cardBg};border:1px solid ${LIGHT.cardBorder};border-radius:12px;overflow:hidden;">

            <!-- Header band: justpae's ink colour, wordmark hosted as a PNG
                 so it renders identically everywhere, incl. clients that
                 strip the <style> block above. Served from this repo's
                 public/email/ (deployed at justpae.com/email/...), not an
                 arbitrary external host — the same reason it's a PNG, not a
                 web font: nothing here depends on a resource this app
                 doesn't itself control. -->
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              <tr>
                <td bgcolor="${LIGHT.headerBg}" style="background-color:${LIGHT.headerBg};padding:20px 28px;">
                  <img src="https://justpae.com/email/justpae-logo@2x.png" width="122" height="40" alt="justpae" style="display:block;border:0;outline:none;">
                </td>
              </tr>
            </table>

            <!-- Body -->
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              <tr>
                <td style="padding:28px 28px 0 28px;">
                  <h1 class="email-heading" style="margin:0;font-family:${FONT};font-size:26px;font-weight:600;color:${LIGHT.heading};">${heading}</h1>
                  ${paragraphs(bodyParagraphs, LIGHT.body, "email-body")}
                </td>
              </tr>
              ${
                panelHtml
                  ? `<tr>
                <td style="padding:20px 28px 0 28px;">
                  ${panelHtml}
                </td>
              </tr>`
                  : ""
              }
              ${
                button
                  ? `<tr>
                <td align="center" style="padding:28px 28px 0 28px;">
                  ${bulletproofButton(button)}
                </td>
              </tr>`
                  : ""
              }
              ${
                button || closingParagraphs.length
                  ? `<tr>
                <td style="padding:20px 28px 0 28px;">
                  ${
                    button
                      ? `<p class="email-muted" style="margin:0;font-family:${FONT};font-size:13px;line-height:1.5;color:${LIGHT.muted};">${fallbackIntro}</p>
                  <p class="email-muted" style="margin:8px 0 0 0;font-family:${MONO};font-size:12px;line-height:1.5;color:${LIGHT.muted};word-break:break-all;">${button.href}</p>`
                      : ""
                  }
                  ${closingParagraphs
                    .map(
                      (p) =>
                        `<p class="email-muted" style="margin:${button ? 18 : 0}px 0 0 0;font-family:${FONT};font-size:13px;line-height:1.5;color:${LIGHT.muted};">${p}</p>`,
                    )
                    .join("\n")}
                </td>
              </tr>`
                  : ""
              }
              <tr>
                <td style="padding:28px 28px 28px 28px;">
                  <p class="email-footer-text" style="margin:0;font-family:${FONT};font-size:12px;line-height:1.5;color:${LIGHT.footerText};">
                    justpae &middot; Zadok Royal Limited${address ? `<br>${address}` : ""}<br>
                    <a href="https://justpae.com/support" class="email-footer-text" style="color:${LIGHT.footerText};">Support</a>
                    &nbsp;&middot;&nbsp;
                    <a href="https://justpae.com/terms" class="email-footer-text" style="color:${LIGHT.footerText};">Terms</a>
                    &nbsp;&middot;&nbsp;
                    <a href="https://justpae.com/privacy" class="email-footer-text" style="color:${LIGHT.footerText};">Privacy</a>
                  </p>
                </td>
              </tr>
            </table>

          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>
</body>
</html>
`;
}

/**
 * The plain-text sibling every HTML email needs, not as a formality but
 * because a meaningful share of real inboxes render it instead of the HTML
 * part — a corporate client that strips HTML for a security scan, a screen
 * reader that prefers it, a client that failed to parse the table markup.
 * Without one, those readers get Resend's own auto-generated stripped-tag
 * fallback, which keeps raw href URLs and drops the paragraph breaks that
 * make the HTML version readable.
 *
 * Built from the exact same EmailOptions the HTML version renders from, so
 * the two can never drift the way a hand-written second copy would.
 */
function stripHtml(value: string): string {
  return value
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, " ")
    .trim();
}

export function renderEmailText(options: EmailOptions): string {
  const { heading, bodyParagraphs, button, fallbackIntro, closingParagraphs = [] } = options;

  const lines: string[] = [heading, ""];
  for (const p of bodyParagraphs) lines.push(stripHtml(p), "");

  if (button) {
    lines.push(`${button.label}: ${button.href}`, "");
    if (fallbackIntro) lines.push(stripHtml(fallbackIntro), button.href, "");
  }

  for (const p of closingParagraphs) lines.push(stripHtml(p), "");

  const address = companyAddress();
  lines.push(
    "—",
    address ? `justpae · Zadok Royal Limited · ${address}` : "justpae · Zadok Royal Limited",
    "Support: https://justpae.com/support",
    "Terms: https://justpae.com/terms  ·  Privacy: https://justpae.com/privacy",
  );

  // Collapse runs of blank lines the paragraph loop above produces.
  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trim() + "\n";
}
